    const n = big ? 100000 : r.int(2, 8);
    const perm = r.shuffle(Array.from({ length: n }, (_, i) => i)), edges = [];
    for (let i = 1; i < n; i++) {
      const p = big && r.bool(0.5) ? i - 1 : r.int(0, i - 1);
      edges.push(r.bool() ? [perm[p], perm[i]] : [perm[i], perm[p]]);
    }
    return [n, r.shuffle(edges)];
  }

