function flipsFromEachStart(n: number, edges: number[][]): number[] {
  const adj: [number, number][][] = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) { adj[u].push([v, 0]); adj[v].push([u, 1]); }
  const answer: number[] = [];
  for (let s = 0; s < n; s++) {
    const seen = new Array(n).fill(false);
    const stack = [s];
    seen[s] = true;
    let flips = 0;
    while (stack.length) {
      const u = stack.pop()!;
      for (const [v, w] of adj[u]) if (!seen[v]) { seen[v] = true; flips += w; stack.push(v); }
    }
    answer.push(flips);
  }
  return answer;
}

