function flipsFromEachStart(n: number, edges: number[][]): number[] {
  const adj: [number, number][][] = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) { adj[u].push([v, 0]); adj[v].push([u, 1]); }
  // BFS order from 0, remembering how each node was reached
  const order = [0], parent = new Array(n).fill(-1), cost = new Array(n).fill(0);
  const seen = new Array(n).fill(false);
  seen[0] = true;
  let root = 0;
  for (let h = 0; h < order.length; h++) {
    const u = order[h];
    for (const [v, w] of adj[u]) {
      if (seen[v]) continue;
      seen[v] = true; parent[v] = u; cost[v] = w; root += w;
      order.push(v);
    }
  }
  const answer = new Array(n).fill(0);
  answer[0] = root;
  for (let h = 1; h < order.length; h++) {
    const c = order[h];
    answer[c] = answer[parent[c]] + (cost[c] === 0 ? 1 : -1);
  }
  return answer;
}

